#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Os valores do deploy ficam num arquivo próprio (gitignored por .env.*), longe do .env do compose.
ENV_FILE="${ENV_FILE_DEPLOY:-.env.deploy}"
RENDER_ESPERADO="https://joya-pedidos-api.onrender.com"
VERCEL_ESPERADO="https://joya-pedidos.vercel.app"
IMAGEM_SQLCMD="mcr.microsoft.com/mssql/server:2022-CU28-ubuntu-22.04"

cd "$(git rev-parse --show-toplevel)"

banner "Deploy online: Azure SQL Free, API no Render, frontend na Vercel (ADR 0007)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Azure: servidor e banco JoyaPedidos (Free Offer)"
say "Vamos criar o SQL Server gerenciado e o banco gratuito."
open_url "https://portal.azure.com/#create/Microsoft.SQLDatabase"
step "No topo, clique em 'Apply offer' (Free Offer: 100 mil vCore-segundos e 32 GB por mês)."
step "Database name: JoyaPedidos (exatamente: no Azure o USE dos scripts não troca de banco)."
step "Server → Create new. Authentication method: 'Use SQL authentication'. Crie o admin e a senha."
step "Behavior when free limit reached: 'Auto-pause the database until next month' (sem cobrança)."
step "Networking: Public endpoint. 'Allow Azure services': No. 'Add current client IP address': Yes."
step "Review + create → Create. Espere o deploy terminar e abra o servidor."
ask SERVIDOR_SQL "Server name (ex.: joya-pedidos.database.windows.net):"
ask USUARIO_SQL "Login do admin:"
ask_secret SENHA_ADMIN_SQL "Senha do admin:"
write_env SERVIDOR_SQL "$SERVIDOR_SQL"
write_env USUARIO_SQL "$USUARIO_SQL"
write_env SENHA_ADMIN_SQL "$SENHA_ADMIN_SQL"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Azure: aplicar os scripts de database/"
say "Os mesmos scripts do compose, pelo mesmo aplicar-scripts.sh, num container com o sqlcmd."
if [[ -z "$(_existing SENHA_API || true)" ]]; then
  # Maiúscula, minúscula, dígito e símbolo para a política de senha; sem ' ; $ para não quebrar SQL nem connection string.
  # Sem "joya" nem "api": o Azure recusa senha com um pedaço de 3+ letras do nome do login (joya_api).
  write_env SENHA_API "Pedidos_$(openssl rand -hex 16)_Z9"
else
  SENHA_API=$(_existing SENHA_API)
  note "Usando a SENHA_API já salva em $ENV_FILE."
fi
note "Cria o usuário contido joya_api, o schema, a carga de exemplo e o volume de 50 mil Pedidos."
if confirm "Aplicar os scripts em $SERVIDOR_SQL/JoyaPedidos agora?"; then
  # As senhas vão pelo ambiente (-e NOME sem valor), não pela linha de comando que a lista de processos mostra.
  export SENHA_ADMIN_SQL SENHA_API
  docker run --rm -v "$PWD/database:/database:ro" \
    -e SERVIDOR_SQL="$SERVIDOR_SQL" -e BANCO_SQL=JoyaPedidos -e USUARIO_SQL="$USUARIO_SQL" \
    -e SENHA_ADMIN_SQL -e SENHA_API -e CONFIAR_CERTIFICADO=nao \
    --entrypoint /bin/bash "$IMAGEM_SQLCMD" /database/init/aplicar-scripts.sh
else
  SKIPPED+=("aplicar os scripts de database/ no Azure (rode o wizard de novo)")
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Render: criar a API pelo render.yaml"
warn "O Render lê o render.yaml da branch escolhida: use a main depois do merge do PR do #8."
open_url "https://dashboard.render.com/blueprints"
step "New Blueprint Instance → conecte o repositório joya-fullstack-solution → branch main."
step "O Render pede o valor de ConnectionStrings__Pedidos. Cole esta linha (é segredo, não compartilhe):"
printf '\n    Server=tcp:%s,1433;Database=JoyaPedidos;User ID=joya_api;Password=%s;Encrypt=True;TrustServerCertificate=False;Connection Timeout=15\n\n' \
  "$SERVIDOR_SQL" "$SENHA_API"
step "Apply. O primeiro deploy pode falhar no health check: o firewall do Azure ainda não libera o Render."
ask RENDER_URL "URL do serviço (ex.: $RENDER_ESPERADO):"
RENDER_URL="${RENDER_URL%/}"
write_env RENDER_URL "$RENDER_URL"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Azure: liberar no firewall os IPs de saída do Render"
step "No Render: serviço joya-pedidos-api → Connect → aba Outbound → copie os IPs."
open_url "https://portal.azure.com/#browse/Microsoft.Sql%2Fservers"
step "No Azure: servidor → Security → Networking → Firewall rules → '+ Add a firewall rule'."
step "Uma regra por IP do Render (Start IP = End IP = o IP). Save."
step "Volte ao Render → Manual Deploy → Deploy latest commit, se o primeiro deploy falhou."
pause "Feito? Enter para conferir o /health."

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Render: conferir GET /health"
note "O plano gratuito hiberna: a primeira resposta leva cerca de 50 s, mais a retomada do banco."
saudavel=nao
for _ in $(seq 1 12); do
  if curl --silent --max-time 60 "$RENDER_URL/health" | grep -q Healthy; then saudavel=sim; break; fi
  note "Ainda não... nova tentativa em 15 s."; sleep 15
done
if [[ "$saudavel" == "sim" ]]; then
  say "${GREEN}✓ $RENDER_URL/health respondeu Healthy.${RESET}"
else
  warn "O /health não ficou Healthy. Veja os logs do serviço no Render e o firewall do Azure."
  SKIPPED+=("API do Render saudável em $RENDER_URL/health")
fi
if [[ "$RENDER_URL" != "$RENDER_ESPERADO" ]]; then
  # -i.bak funciona no sed do GNU e no do macOS.
  sed -i.bak "s#$RENDER_ESPERADO#$RENDER_URL#" frontend/vercel.json && rm -f frontend/vercel.json.bak
  warn "A URL difere da esperada: frontend/vercel.json foi atualizado. Faça commit e push antes da Vercel."
  SKIPPED+=("commit e push de frontend/vercel.json com $RENDER_URL")
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Vercel: publicar o frontend"
open_url "https://vercel.com/new"
step "Import Git Repository → joya-fullstack-solution."
step "Project Name: joya-pedidos. Root Directory: frontend (o vercel.json de lá faz o resto)."
step "Sem variáveis de ambiente: o front só chama /api, e a Vercel repassa para o Render (ADR 0011)."
step "Deploy. Copie o domínio de produção (Settings → Domains)."
ask VERCEL_URL "URL do frontend (ex.: $VERCEL_ESPERADO):"
VERCEL_URL="${VERCEL_URL%/}"
write_env VERCEL_URL "$VERCEL_URL"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Vercel: conferir o rewrite e os headers"
if curl --silent --max-time 90 "$VERCEL_URL/api/health" | grep -q Healthy; then
  say "${GREEN}✓ $VERCEL_URL/api/health chega na API pela mesma origem.${RESET}"
else
  warn "$VERCEL_URL/api/health não respondeu Healthy."
  SKIPPED+=("rewrite /api da Vercel")
fi
headers=$(curl --silent --head --max-time 30 "$VERCEL_URL/")
for header in content-security-policy x-content-type-options referrer-policy; do
  if grep -qi "^$header:" <<<"$headers"; then say "${GREEN}✓ $header${RESET}"
  else warn "faltou o header $header"; SKIPPED+=("header $header na Vercel"); fi
done
if [[ "$VERCEL_URL" != "$VERCEL_ESPERADO" ]]; then
  sed -i.bak "s#$VERCEL_ESPERADO#$VERCEL_URL#g" README.md && rm -f README.md.bak
  warn "README.md atualizado com $VERCEL_URL. Faça commit."
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Ponta a ponta no ambiente online"
open_url "$VERCEL_URL"
step "Crie um Pedido, veja-o na listagem e abra a aba Top Clientes."
note "Os E2E passam pelo mesmo limite de 100 requisições por minuto do IP de saída da Vercel (ADR 0015)."
if confirm "Rodar também os E2E do Playwright contra $VERCEL_URL? (cria Pedidos no banco online)"; then
  (cd frontend && BASE_URL="$VERCEL_URL" npx playwright test) || SKIPPED+=("E2E online falharam: veja frontend/playwright-report")
fi
pause

finish
}

run_wizard "$@"; exit
